#!/usr/bin/env python3
"""Generate docs/hive/VISUAL_SPEC.md from docs/hive/measurements/{target.json, ours-before-*.json}.

Every number in the measured tables comes from those JSON files (produced by tools/measure_target.py and
tools/measure_ours.mjs); narrative sections are plain text in this script. Re-run after re-measuring:
    python tools/measure_target.py && node tools/measure_ours.mjs before && python tools/make_visual_spec.py
"""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
M = ROOT / "docs/hive/measurements"
T = json.loads((M / "target.json").read_text())
SIZES = [(1280, 720), (1920, 1080), (2560, 1440)]
O = {w: json.loads((M / f"ours-before-{w}x{h}.json").read_text()) for w, h in SIZES}
W, H = T["image_px"]["w"], T["image_px"]["h"]
CAP = 0.72  # cap height / font size for a typical humanist sans; the measured fonts are Inter-like


def pct(v, base, d=1):
    return f"{v / base * 100:.{d}f}"


# ---------------------------------------------------------------- planned stage transform (CORE centred per spec)
ring = T["core"]["neon_ring"]
S = 0.985  # uniform scale about the CORE centre column / vertical centre
def tx(x): return W / 2 + (x - ring["cx"]) * S
def ty(y): return H / 2 + (y - H / 2) * S
planned = {}
for k, p in T["panels"].items():
    planned[k] = {"x0": tx(p["x0"]), "y0": ty(p["y0"]), "x1": tx(p["x1"]), "y1": ty(p["y1"])}
    planned[k]["w"] = planned[k]["x1"] - planned[k]["x0"]; planned[k]["h"] = planned[k]["y1"] - planned[k]["y0"]
core_planned = {"cx": W / 2, "cy": ty(ring["cy"]), "r": ring["r"] * S}
# a panel set that could break the 10 px minimum gutter at 1280x720 (k = 1280/1671)
K1280 = 1280 / W
tight = {k: v * S * K1280 for k, v in T["gutters_px"].items() if isinstance(v, (int, float)) and v * S * K1280 < 10.0}

(M / "layout-spec.json").write_text(json.dumps({
    "note": "Planned normalised layout = measured target panels with a uniform scale S about the ring centre column so the CORE is exactly centred. Coordinates in a 1671x941 reference stage.",
    "reference_stage_px": {"w": W, "h": H}, "scale_S": S, "core_centre_px": {"x": W / 2, "y": core_planned["cy"]}, "core_ring_radius_px": core_planned["r"],
    "panels_px": {k: {kk: round(vv, 1) for kk, vv in v.items()} for k, v in planned.items()},
    "panels_normalised": {k: {"x": round(v["x0"] / W, 4), "y": round(v["y0"] / H, 4), "w": round(v["w"] / W, 4), "h": round(v["h"] / H, 4)} for k, v in planned.items()},
}, indent=1))

L = []
a = L.append
a("# HIVE dashboard - visual specification (measured)")
a("")
a("**Status:** measurement + plan. GAP-5 stays OPEN. Nothing in this document is data for the dashboard: the target image is visual direction only, and every number, name, provider mapping and status in it (72 %, 1.31 TB, \"Online\", \"ACTIVE\", Admin, ...) is illustrative and is never reproduced as a value.")
a("")
a("Generated by `tools/make_visual_spec.py` from `docs/hive/measurements/target.json` (tools/measure_target.py) and `ours-before-*.json` (tools/measure_ours.mjs, baseline commit f37affd). Target tolerance about +-2 px at 1671x941. Side-by-side and overlay images: `docs/hive/screenshots/compare-after-*.png` (previous phase), `overlay-before-*.png` (target outlines drawn over the current UI).")
a("")
a("## 1. Architecture: local-first hybrid 2.5D")
a("""```
layer 0  WALLPAPER   one local raster (nebula + stars + circuit traces ONLY), CSS background, cover-fit        [decorative, static]
layer 1  CORE ART    local canvas (vortex/accretion, pre-rendered once) + local SVG (rings, ring nodes,           [decorative + state tint]
                     connector curves, agent icons, planet); parallax = at most a tiny CSS transform
layer 2  STAGE       a 16:9 reference stage (1671x941 units) scaled by k = min(vw/1671, vh/941); DOM panels are   [truth]
                     absolutely positioned on it from the planned rectangles in section 3.1
layer 3  LIVE DOM    every label, number, status, row, button, approval and chip is HTML/SVG-text in the DOM,     [truth]
                     driven by hive-core.js / hive-ops.js; nothing live is ever drawn into a raster
```
Rules: no Unity, no remote Spline embed, no CDN/runtime fetch; all assets are files in this repository and are served by the local server; no text, telemetry, numbers, provider states or approvals in any raster; reduced motion disables every animation; UNKNOWN/UNVERIFIED states keep their dim, desaturated look (the wallpaper never changes with state); `hive-core.js` remains the source of truth for CORE state, movement and transport.""")
a("")
a("### 1.1 Stage scaling and viewports that are not 16:9")
a(f"k = min(vw/{W}, vh/{H}). The stage is centred; the wallpaper fills the whole viewport (cover). At 1280x720, 1920x1080 and 2560x1440 k = {1280/W:.3f}, {1920/W:.3f}, {2560/W:.3f}. A wider or taller window letterboxes the stage over the wallpaper (no distortion, no extra panels). Absolute minimums stay in force: gutters >= 10 px, body text >= 10 px, so `max(10px, calc(var(--k) * N))` is used where the scaled value would drop below them.")
a("")
a("## 2. Target geometry (measured), 1671 x 941")
a("")
a("### 2.1 Panels")
a("| Panel | x0 | y0 | w | h | x0 % W | y0 % H | w % W | h % H |")
a("|---|---|---|---|---|---|---|---|---|")
for k, p in T["panels"].items():
    a(f"| {k} | {p['x0']} | {p['y0']} | {p['w']} | {p['h']} | {pct(p['x0'], W)} | {pct(p['y0'], H)} | {pct(p['w'], W)} | {pct(p['h'], H)} |")
a("")
a("The top bar has no measurable panel border: it is a transparent row of items (logo, status, source chips, ULTRON badge, JARVIS pill, clock + date, bell, settings, user) spanning x 33..1640, y 8..48.")
a("")
a("### 2.2 Gutters (px at 1671 wide; the target is not a grid)")
a("| Gap | px | % of W |")
a("|---|---|---|")
for k, v in T["gutters_px"].items():
    if isinstance(v, (int, float)):
        a(f"| {k} | {v} | {pct(v, W, 2)} |")
a("")
a(f"Smallest measured gutter is {min(v for v in T['gutters_px'].values() if isinstance(v, (int, float)))} px, i.e. {min(v for v in T['gutters_px'].values() if isinstance(v, (int, float))) * K1280:.1f} px at 1280x720. The spec's minimum is 10 px, so any gutter below 10 px after scaling is raised to 10 px (affected: {', '.join(sorted(tight)) or 'none'}).")
a("")
a("### 2.3 Observations that contradict the current implementation")
t = T["panels"]
a(f"- **Rails are not full height.** Target left rail ends at y = {t['agents']['y1']} ({pct(t['agents']['y1'], H)} % of H) and the right rail at y = {t['approvals']['y1']} ({pct(t['approvals']['y1'], H)} %); the composer ends at {t['composer']['y1']} ({pct(t['composer']['y1'], H)} %). The implementation anchors both rails to the composer line (last phase). That choice was wrong for parity.")
a(f"- **Rails are unequal.** Left rail width {t['chats']['w']} px ({pct(t['chats']['w'], W)} % W), right rail {t['activity']['w']} px ({pct(t['activity']['w'], W)} % W). The implementation uses two equal rails of 17 % W.")
a(f"- **The card row spans the centre only** (x {t['card_current']['x0']}..{t['card_layout']['x1']}), not the full width between the rails, and the five cards have different widths ({t['card_current']['w']}, {t['card_next']['w']}, {t['card_context']['w']}, {t['card_external']['w']}, {t['card_layout']['w']} px).")
a(f"- **The CORE is not horizontally centred in the target:** ring centre x = {ring['cx']} ({pct(ring['cx'], W, 2)} % W; centred would be 50 %), i.e. {W / 2 - ring['cx']:.1f} px left of centre. The project spec requires the CORE centred; see 3.1 for the transform that satisfies both.")
a(f"- **The composer is offset** (x {t['composer']['x0']}..{t['composer']['x1']}, centre {(t['composer']['x0'] + t['composer']['x1']) / 2:.0f} px = {pct((t['composer']['x0'] + t['composer']['x1']) / 2, W, 1)} % W) and resources+limits are centred under the CORE ({(t['resources']['x0'] + t['limits']['x1']) / 2:.0f} px).")
a("")
a("## 3. Planned layout (PLAN: not built yet)")
a(f"### 3.1 CORE centring transform")
a(f"Uniform scale S = {S} about the CORE column (x' = {W / 2:.1f} + (x - {ring['cx']}) * S) and about the vertical centre (y' = {H / 2:.1f} + (y - {H / 2:.1f}) * S). Result: ring centre ({W / 2:.1f}, {core_planned['cy']:.1f}), ring radius {core_planned['r']:.1f}; leftmost panel edge {min(v['x0'] for v in planned.values()):.1f} px, rightmost {max(v['x1'] for v in planned.values()):.1f} px (right margin {W - max(v['x1'] for v in planned.values()):.1f} px, left margin {min(v['x0'] for v in planned.values()):.1f} px: the asymmetry is inherited from the target). Final rectangles: `docs/hive/measurements/layout-spec.json`.")
a("")
a("| Panel | x0 | y0 | w | h | x % W | y % H | w % W | h % H |")
a("|---|---|---|---|---|---|---|---|---|")
for k, p in planned.items():
    a(f"| {k} | {p['x0']:.1f} | {p['y0']:.1f} | {p['w']:.1f} | {p['h']:.1f} | {pct(p['x0'], W)} | {pct(p['y0'], H)} | {pct(p['w'], W)} | {pct(p['h'], H)} |")
a("")
a("## 4. Current implementation vs target (panels, normalised to the viewport)")
a("Implementation = fixture data, CSS-grid shell (baseline f37affd). Differences in percentage points of W (x, w) or H (y, h); target = measured, **not** the planned transform.")
for w, h in SIZES:
    a("")
    a(f"### {w}x{h}")
    a("| Panel | ours x % | ours y % | ours w % | ours h % | dx pp | dy pp | dw pp | dh pp |")
    a("|---|---|---|---|---|---|---|---|---|")
    o = O[w]["panels"]
    for k, p in T["panels"].items():
        if k not in o:
            continue
        q = o[k]
        tx_, ty_, tw_, th_ = p["x0"] / W * 100, p["y0"] / H * 100, p["w"] / W * 100, p["h"] / H * 100
        ox, oy, ow, oh = q["x0"] / w * 100, q["y0"] / h * 100, q["w"] / w * 100, q["h"] / h * 100
        flag = " **" if max(abs(ox - tx_), abs(oy - ty_), abs(ow - tw_), abs(oh - th_)) > 2.0 else ""
        a(f"| {k}{flag} | {ox:.1f} | {oy:.1f} | {ow:.1f} | {oh:.1f} | {ox - tx_:+.1f} | {oy - ty_:+.1f} | {ow - tw_:+.1f} | {oh - th_:+.1f} |")
a("")
a("`**` = more than 2 percentage points off the target in at least one dimension.")
a("")
a("## 5. CORE geometry")
n = T["core"]
a(f"Target (px at {W}x{H}): neon ring centre ({ring['cx']}, {ring['cy']}), radius {ring['r']} ({pct(ring['r'], H)} % of H); event-horizon dark disc centre ({n['horizon']['cx']}, {n['horizon']['cy']}), equivalent radius {n['horizon']['r_equiv']} ({n['horizon']['r_equiv'] / ring['r']:.3f} of ring radius); planet centre ({n['planet']['cx']}, {n['planet']['cy']}), radius ~{n['planet_radius_px_estimate']} (estimate); node radius ~{n['node_radius_px_estimate']} (estimate).")
a("")
a("| Element | target angle deg | target r / ring | ours angle deg (1920) | ours r / ring | ours r px (1920) | target r px (scaled to 1080) |")
a("|---|---|---|---|---|---|---|")
sc = 1080 / H
for k, pol in n["polar"].items():
    oo = O[1920]["core"]["polar"].get(k)
    r_t = n["node_radius_px_estimate"] * sc if k not in ("INTERNET_planet",) else n["planet_radius_px_estimate"] * sc
    r_o = O[1920]["core"]["nodes"].get(k, {}).get("r") if k != "INTERNET_planet" else O[1920]["core"]["planet"]["r"]
    a(f"| {k} | {pol['angle_deg']} | {pol['r_over_ring']} | {oo['angle_deg'] if oo else '-'} | {oo['r_over_ring'] if oo else '-'} | {r_o if r_o is not None else '-'} | {r_t:.1f} |")
a("")
a(f"Ring: target {ring['r'] / H * 100:.1f} % of H vs ours {O[1920]['core']['ultron_ring']['r'] / 1080 * 100:.1f} % at 1920x1080 ({O[1280]['core']['ultron_ring']['r'] / 720 * 100:.1f} % at 1280, {O[2560]['core']['ultron_ring']['r'] / 1440 * 100:.1f} % at 2560). Horizon: target {n['horizon']['r_equiv'] / H * 100:.1f} % of H vs ours {O[1920]['core']['horizon']['r'] / 1080 * 100:.1f} %. Planet radius: target ~{n['planet_radius_px_estimate'] / H * 100:.1f} % vs ours {O[1920]['core']['planet']['r'] / 1080 * 100:.1f} %. Node radius: target ~{n['node_radius_px_estimate'] / H * 100:.1f} % vs ours {O[1920]['core']['nodes']['FURY']['r'] / 1080 * 100:.1f} %.")
a("")
a(f"**Correction of docs/hive/VISUAL_REVIEW.md 6.1:** that section estimated the target ring at ~48 % of image height by eye. Measured, the ring diameter is {2 * ring['r'] / H * 100:.1f} % of H. Our ring diameter is {2 * O[1920]['core']['ultron_ring']['r'] / 1080 * 100:.1f} % at 1920x1080, {2 * O[1280]['core']['ultron_ring']['r'] / 720 * 100:.1f} % at 1280x720 and {2 * O[2560]['core']['ultron_ring']['r'] / 1440 * 100:.1f} % at 2560x1440, i.e. {O[1920]['core']['ultron_ring']['r'] / 1080 / (ring['r'] / H) * 100:.0f} %, {O[1280]['core']['ultron_ring']['r'] / 720 / (ring['r'] / H) * 100:.0f} % and {O[2560]['core']['ultron_ring']['r'] / 1440 / (ring['r'] / H) * 100:.0f} % of the target's. The CORE is modestly under-scaled (not 'about half', and not 'close' either).")
a("")
a("Findings: the agents are **not** on one circle in the target (r / ring from 0.525 for UATU to 0.777 for THOR; angles FURY -89, THOR -42, FALCON 26, UATU 90, VISION 155, SHURI -136) - ours sit on r / ring = 0.75 at -90/-150/-30/150/30 plus UATU. ULTRON sits on the ring (0.975). Target nodes and planet are ~1.7x and ~1.2x larger than ours.")
a("")
a("### 5.1 Context label groups (target, px at 1671x941; rows read by bright-pixel clustering)")
a("| Group | row centres y | left x | row pitch |")
a("|---|---|---|---|")
for k, rows in T["label_groups"].items():
    rr = [r for r in rows if "y_centre" in r]
    pitch = next((r["row_pitch_px_median"] for r in rows if "row_pitch_px_median" in r), "-")
    a(f"| {k} | {', '.join(str(r['y_centre']) for r in rr)} | {min(r['x_left'] for r in rr)} | {pitch} |")
a("")
a("The fifth group (Logs / Patterns / Anomalies) is **not implemented**: the spec forbids a visible LOGS section and a test enforces its absence. All label groups render dim and \"not observed\" until a fresh trusted event names them.")
a("")
a("## 6. Typography")
a(f"Target values are cap heights of UPPERCASE samples measured in px at {W}x{H}; implementation values are computed font sizes (SVG text through the screen CTM). Cap height of the implementation = font size x {CAP} (assumption for the Inter-like face; +-5 %). All comparisons normalised to image/viewport height.")
a("")
MAP = [("panel_title_CHATS", "panel_title"), ("node_name_FURY", "node_name"), ("approval_label_GPT", "approval_label"), ("gauge_label_CPU", "gauge_label"),
       ("internet_label", "internet_label"), ("top_HIVE", "top_brand")]
a("| Element | target cap px | target cap % H | target font px (cap/0.72) | ours 1280 cap % H | ours 1920 cap % H | ours 2560 cap % H | ours / target (1920) |")
a("|---|---|---|---|---|---|---|---|")
for tk, ok in MAP:
    tv = T["text_cap_heights_px"][tk]["height_px"]
    row = [f"{tk}", f"{tv}", pct(tv, H, 2), f"{tv / CAP:.1f}"]
    ratios = []
    for w, h in SIZES:
        fpx = O[w]["text"].get(ok, {}).get("font_px")
        row.append(pct(fpx * CAP, h, 2) if fpx else "-")
        ratios.append(fpx * CAP / h / (tv / H) if fpx else None)
    row.append(f"{ratios[1]:.2f}" if ratios[1] else "-")
    a("| " + " | ".join(row) + " |")
a("")
a("Other implementation sizes (px, computed): " + "; ".join(f"{k} {v['font_px']} px/{v['weight']}" for k, v in O[1920]["text"].items()) + " (1920x1080).")
a("")
a("Planned base sizes (at the 1671 reference stage, then x k): panel titles 16.7 px, node names 15.3 px (cap 11), approval/GPT labels 14.2 px, gauge labels 15.3 px, top brand 23.6 px; list rows target pitch ~29 px (agents), ~36 px (two-line chats), ~52 px (approval rows), ~24 px (limit rows). Absolute floor 10 px.")
a("")
a("## 7. Colours (target samples are post-blend pixels; ours are computed CSS)")
a("| Item | target RGB | ours (computed CSS) |")
a("|---|---|---|")
tc = T["colours_rgb"]
oc = O[1920]["colours"]
def rgb(v): return f"rgb({v[0]}, {v[1]}, {v[2]})" if v else "n/a (no matching pixels)"
a(f"| panel interior | {rgb(tc['panel_interior_chats'])} / {rgb(tc['panel_interior_activity'])} | {oc['.hive-panel']['background']} over the wallpaper |")
a(f"| panel border | {rgb(tc['panel_border_left_chats'])} (left) / {rgb(tc['panel_border_top_chats'])} (top) | {oc['.hive-panel']['border']} |")
a(f"| Approve button | {rgb(tc['approve_button'])} | {oc['.ap-btn.approve']['background']} bg, {oc['.ap-btn.approve']['border']} border |")
a(f"| Edit button | {rgb(tc['edit_button'])} | {oc['.ap-actions .ap-btn:nth-child(2)']['background']} bg |")
a(f"| Reject button | {rgb(tc['reject_button'])} | {oc['.ap-btn.reject']['background']} bg |")
a(f"| chip GPT / CODEX / CLAUDE | {rgb(tc['chip_gpt'])} / {rgb(tc['chip_codex'])} / {rgb(tc['chip_claude'])} | identity accents #6fa8ff / #b58cff / #f08cd8 (deliberately not status hues) |")
a(f"| gauge CPU / RAM / GPU | {rgb(tc['gauge_cpu'])} / {rgb(tc['gauge_ram'])} / {rgb(tc['gauge_gpu'])} | {oc['.gauge[data-k=\"cpu\"] .g-val']['stroke']} / {oc['.gauge[data-k=\"ram\"] .g-val']['stroke']} / {oc['.gauge[data-k=\"gpu\"] .g-val']['stroke']} |")
a(f"| limit bars GPT / CODEX | {rgb(tc['bar_gpt'])} / {rgb(tc['bar_codex'])} | status-coloured (mint fill) |")
a(f"| ULTRON badge (target 'ACTIVE') | {rgb(tc['ultron_badge_green'])} | **not reproduced**: NOT CONNECTED / gray ring without an ULTRON event |")
a(f"| background nebula violet / blue / dark space | {rgb(tc['background_nebula_violet'])} / {rgb(tc['background_nebula_blue'])} / {rgb(tc['background_dark_space'])} | wallpaper (section 8) |")
a(f"| primary text | {rgb(tc['text_primary_sample'])} (brightest pixels) | {O[1920]['text']['panel_title']['colour']} |")
a("")
a("**Reliability of these samples:** panel interior and button/gauge/chip colours are medians of masked pixels (reasonable, +-10 per channel). The border row/column samples are +-1 px off the real 1-2 px line and disagree (left vs top); a direct probe of the same image gave a muted blue-grey edge of about rgb(57, 79, 95) (left, x=35) and rgb(59, 94, 133) (top, y=79) against an interior of about rgb(24, 40, 70). The three background windows are arbitrary corners, not representative of the nebula; judge the wallpaper visually, not by these numbers. The brightest primary-text pixel is pure white in the target, ours is rgb(230, 244, 255).")
a("")
a("Status colours stay semantic and must not be reused as identity colours: ok #4ff0c0, warn #f2b84b, fail #ff5c6c, unknown #7f93a3, review #b08cff.")
a("")
a("## 8. Wallpaper specification (PLAN: not built yet)")
a("""- Planned: one local file generated by a committed, deterministic script (`tools/make_wallpaper.py`, seeded; Pillow + numpy, dev-time only). The generated JPEG is committed under `assets/` and served locally.
- Content: nebula clouds, star field (several depths), faint circuit traces, subtle dark vignette. **Nothing else.** No text, no digits, no gauges, no rings, no panels, no icons, no provider logos, no UI chrome, no state colours that could be misread as a status.
- Size/format: 2560x1440 (16:9), JPEG q~85, target <= 600 KB; CSS `background: url(...) center/cover`, `background-color` fallback so the shell is usable if the file is missing.
- The wallpaper is static: it never changes with CORE state or data.
- Automated checks planned: file exists, 16:9, byte budget, generator source contains no text-drawing calls, no external URL in html/css/js, zero off-origin requests at runtime, wallpaper hash recorded.""")
a("")
a("## 9. CORE renderer specification and Rive evaluation (PLAN: not built yet; the Rive decision is made now)")
a("""CORE art = a pre-rendered local canvas (accretion disk with additive-blend streaks, glow, lens ring) rotated only by CSS in IDLE/WORKING, plus local SVG for rings, ring nodes, connectors, agent icons and the planet. State tint continues to come from `hive-core.js` (`deriveCoreState` -> `visualClass`) through CSS classes/filters; the renderer is a pure view: `apply({state, tone, motion, reduced})`, no logic of its own.

**Rive: evaluated, not adopted now.** Reasons: (1) it needs a `.riv` file authored in the Rive editor, which is not available here, and a runtime (JS + WASM) that is a large new dependency against the project's "no large dependencies / no WebGL" rule; (2) a canvas/SVG renderer has not yet been tried at the fidelity bar below; (3) any Rive runtime would have to be vendored into the repo (no CDN). **Adoption criteria** (all must hold): after a canvas/SVG attempt the owner still rates the CORE as the main visual gap; a `.riv` authored with state inputs matching the 8 CORE states exists; runtime and asset are vendored locally with licences recorded; state/movement/transport remain in `hive-core.js`; reduced motion pauses the artboard; a canvas fallback remains for UNKNOWN/offline load failure.""")
a("")
a("## 10. Differences, ranked by visual weight (what the next phase changes)")
a(f"1. Layout: absolute normalised stage instead of a full-height 3-column grid (rails shorter, unequal widths, centre-only card row) - sections 2.3/3.")
a(f"2. Type scale: panel titles at {O[1920]['text']['panel_title']['font_px'] * CAP / 1080 * 100:.2f} % of H versus {T['text_cap_heights_px']['panel_title_CHATS']['height_px'] / H * 100:.2f} % in the target; node names/labels similar gap - section 6.")
a(f"3. CORE: ring {O[1920]['core']['ultron_ring']['r'] / 1080 * 100:.1f} % vs {ring['r'] / H * 100:.1f} % of H, nodes and planet ~1.2-1.7x too small, agents on one circle instead of the measured angles/radii - section 5.")
a("4. Background and vortex fidelity: procedural SVG strokes vs a rendered wallpaper and a layered canvas vortex - sections 8/9.")
a("5. List/row density and icons inside the panels (pitches in section 6) - the target's density comes from illustrative content that must not be invented; only the geometry/typography is adopted.")
a("6. Deliberately kept differences (truthfulness): UNKNOWN/gray states, no ACTIVE/Online, no Admin/bell/settings, no Logs label, no provider mapping, disabled Layout controls, English labels.")
a("")
a("## 11. Verification plan")
a("Overlay and side-by-side screenshots at 1280x720, 1920x1080, 2560x1440 (fixture and live-adapter); `tools/measure_ours.mjs <label>` re-measures and this document is regenerated; panel deltas must be <= 1.5 percentage points of W/H except where section 10 lists a deliberate deviation; existing E2E suites (shell, core, chat, system, visual) must keep passing; new checks for wallpaper (no text, local-only, byte budget), stage scaling (k, minimum gutter and text floors), CORE centring (+-2 px), reduced motion. GAP-5 closes only on the owner's explicit acceptance of the side-by-side review.")
(ROOT / "docs/hive/VISUAL_SPEC.md").write_text("\n".join(L) + "\n")
print("wrote docs/hive/VISUAL_SPEC.md,", len(L), "lines; tight gutters:", tight)
